// Vague requirement
// "The API should be fast"

// Clarified requirement
// "When a customer submits an order, the API must return
// a 201 Created response within 200 milliseconds for 99%
// of requests during normal business hours (9 AM - 5 PM EST)."

// Testable acceptance criterion
public class OrderSubmissionTests
{
    [Fact]
    public async Task SubmitOrder_Returns201Within200ms()
    {
        var client = _factory.CreateClient();
        var order = new CreateOrderRequest
        {
            CustomerId = Guid.NewGuid(),
            Items = new[] { new OrderItem { Sku = "ABC", Quantity = 1 } }
        };

        var stopwatch = Stopwatch.StartNew();
        var response = await client.PostAsJsonAsync(
            "/api/orders", order);
        stopwatch.Stop();

        Assert.Equal(HttpStatusCode.Created, response.StatusCode);
        Assert.True(stopwatch.ElapsedMilliseconds <= 200,
            $"Expected <= 200ms, got {stopwatch.ElapsedMilliseconds}ms");
    }
}

public class CreateOrderRequest
{
    public Guid CustomerId { get; set; }
    public List<OrderItemDto> Items { get; set; } = new();
    public decimal MaxTotalAmount { get; set; }
}

public class CreateOrderValidator : AbstractValidator<CreateOrderRequest>
{
    public CreateOrderValidator()
    {
        RuleFor(x => x.CustomerId)
            .NotEmpty().WithMessage("Customer is required.");

        RuleFor(x => x.Items)
            .NotEmpty().WithMessage("At least one item is required.");

        RuleFor(x => x.MaxTotalAmount)
            .GreaterThan(0).WithMessage("Amount must be positive.")
            .LessThanOrEqualTo(100_000)
            .WithMessage("Order exceeds maximum allowed amount.");

        RuleForEach(x => x.Items).ChildRules(item =>
        {
            item.RuleFor(i => i.Sku)
                .NotEmpty().MaximumLength(50);
            item.RuleFor(i => i.Quantity)
                .GreaterThan(0).LessThanOrEqualTo(1000);
        });
    }
}
